from author import *
c=C('曲线积分与格林公式')
S(c,'第一类曲线积分：弧长元ds',[R('参数化与弧长元',r'\mathbf r(t)=(x(t),y(t),z(t)),\quad ds=|\mathbf r^{\prime}(t)|dt'),R('单位上半圆',r'x=\cos t,\quad y=\sin t,\quad0\leq t\leq\pi'),R('长度',r'\int_L1\,ds=\int_0^\pi1\,dt=\pi')],[P('先沿单位上半圆走一遍。第一类曲线积分使用弧长元ds，做题通常先给曲线选参数，再把弧长元换成坐标导数的平方和开根号乘dt。单位圆用余弦t、正弦t，上半圆t从零到π。两个导数平方和为一，所以本题弧长元刚好等于dt，别把这个特殊结果用于所有曲线。',[1,2],['第一类使用弧长元，不是直接使用dx','先参数化，再算导数的长度'],phase='arc',anchor='先沿单位上半圆走一遍'),P('现在把已经走过的弧长累计起来。对常数一积分，就是曲线长度，因此上半圆得到π。弧长元是非负的几何长度，第一类曲线积分与曲线方向无关；反向遍历同一条曲线，积分值不变。若参数沿反方向变化，要正确处理参数范围和速度长度，不能误给弧长元添一个负号。',[3],['第一类不因反向而变号','本题得到上半圆长度π'],phase='length',anchor='现在把已经走过的弧长累计起来')],['第一类曲线积分'],visual=G('semicircle'))
S(c,'第一类带权积分：函数也要代参数',[R('同一条单位上半圆',r'\mathbf r(t)=(\cos t,\sin t),\quad0\leq t\leq\pi'),R('被积函数与弧长元',r'y=\sin t,\quad ds=dt'),R('计算',r'\int_L y\,ds=\int_0^\pi\sin t\,dt=2')],[P('做第一类带权题，除了换弧长元，还要把被积函数一起改成参数。本题被积函数y，沿单位圆应换成正弦t，弧长元仍为dt，因此变成一个普通定积分。若只写出ds等于dt，却把y留在对t的积分里，说明变量替换还没完成，应先把所有坐标都统一为参数表达式。',[1,2],['被积函数和弧长元都要换','一条积分里只保留正确的积分变量']),P('正弦t从零到π积分得到二。这不是曲线长度，而是沿曲线按高度y加权后的结果；同一条曲线换一个函数，积分就不同。由于这条曲线上y非负，结果应非负，可以作符号自查。换成反方向仍然是二，第一类的方向无关，不会因为加入权重就突然改变。',[3],['积分结果二；它不是半圆长度','第一类带权积分仍与方向无关'])],['第一类曲线积分'])
S(c,'第二类曲线积分：坐标微分带方向',[R('基本形式',r'\int_L P\,dx+Q\,dy+R\,dz'),R('直线从原点到一、一',r'x=t,\quad y=t,\quad0\leq t\leq1'),R('例题与反向',r'\int_Lx\,dx+y\,dy=\int_0^1 2t\,dt=1;\quad I_{-L}=-1')],[P('第二类曲线积分使用dx、dy、dz这样的坐标微分，因此要考虑方向。平面例题从原点沿直线走到一、一，设x、y都为t，t从零到一，两个微分都是dt。再把P、Q中的坐标换成参数，得到二t的积分，结果一。不要把坐标导数的长度塞进第二类公式，那是另一类题的弧长元。',[1,2],['第二类使用坐标微分，方向重要','参数方向应从指定起点走向终点']),P('若沿同一条直线反向走，第二类积分变为负一，而第一类不会这样变号。计算前先在曲线上画一个箭头，再确定参数起止，能减少整题最后差一个负号的情况。空间曲线还会多一项R乘dz，原则一样：函数代坐标，微分乘相应坐标对参数的导数，再统一对t积分。',[3],['反向使第二类积分变号','不要混用ds与dx、dy、dz'])],['第二类曲线积分'])
S(c,'圆周定向积分的参数化',[R('单位圆逆时针',r'x=\cos t,\quad y=\sin t,\quad0\leq t\leq2\pi'),R('坐标微分',r'dx=-\sin t\,dt,\qquad dy=\cos t\,dt'),R('代入计算',r'\oint_L(-y\,dx+x\,dy)=\int_0^{2\pi}1\,dt=2\pi')],[P('先按逆时针方向沿圆周移动。单位圆最常用的参数化是x余弦t、y正弦t，t从零增加到二π。对参数求导后，dx前有负正弦，dy前是余弦。原积分里负y再乘dx，两个负号相消，得到正弦平方；另一项是余弦平方，两项相加为一。',[1,2],['余弦求导的负号不能漏','逆时针与参数递增方向配套'],phase='ccw',anchor='先按逆时针方向沿圆周移动'),P('现在把走完一圈的贡献累加。结果二π。如果题目改成顺时针，只需对同一积分取相反数；若半径改成a，坐标与坐标微分都会带入一个a，结果变成二π乘a平方。不要只给最终答案乘一次半径，这个例子中出现的是半径平方。',[3],['顺时针结果反号','半径改变时，函数与微分都要变'],phase='accumulate',anchor='现在把走完一圈的贡献累加')],['第二类曲线积分参数化'],visual=G('circle_orientation'))
S(c,'格林公式：边界积分转为区域积分',[R('正向边界的公式',r'\oint_{\partial D}P\,dx+Q\,dy=\iint_D(Q_x-P_y)\,dA'),T('先查条件与方向','闭合边界分段光滑；P、Q在区域邻域内一阶偏导连续'),R('例题',r'P=-y,\quad Q=x:\quad Q_x-P_y=2,\quad I=2S(D)')],[P('先把封闭边界和它围住的区域一起标出。格林公式把第二类闭曲线积分转成二重积分，顺序是Q对x减P对y。要有适当光滑的封闭边界，P、Q在包含区域的邻域有连续一阶偏导。没有封闭的曲线不能直接套；若人为补边，就要把补上的积分另外减回去。',[1,2],['顺序是Q对x减P对y','闭合、光滑与定义域条件先检查'],phase='boundary',anchor='先把封闭边界和它围住的区域一起标出'),P('现在把边界的计算转移到内部小块。正向是沿边界前进时，区域在左侧，外边界逆时针；有洞的内边界则顺时针。本例P负y、Q为x，两项偏导相减得到二，所以直接等于区域面积的二倍。单位圆又得到二π，与参数法一致，可以互相检查方向和符号。',[3],['有洞时，内外边界方向相反','本例积分是区域面积二倍'],phase='area',anchor='现在把边界的计算转移到内部小块')],['格林公式'],visual=G('green'))
S(c,'路径无关：偏导相等还要看区域',[T('常用充分条件','单连通区域内，P、Q具有连续一阶偏导，且Py=Qx'),R('例题',r'P=2xy,\quad Q=x^2,\quad d(x^2y)=Pdx+Qdy'),R('起终点计算',r'\int_{(0,0)}^{(1,2)}Pdx+Qdy=[x^2y]_{(0,0)}^{(1,2)}=2'),T('有洞的反例','去掉原点的平面上，绕原点一圈可能不为零；不能只看Py等于Qx')],[P('若能找到一个函数u，使它的全微分等于Pdx加Qdy，积分就只由终点u减起点u决定。在P、Q有连续一阶偏导、区域单连通等常用条件下，P对y等于Q对x可以用来判断路径无关。本题势函数是x平方乘y，所以从原点到一、二，直接算终点二减起点零。',[1,2,3],['先检查区域与连续性条件','有势函数时用终点值减起点值']),P('单连通在这里可以粗略理解为区域没有导致路径绕行的洞，但判断仍以题设定义域为准。经典反例是在去掉原点的平面上取负y除以平方和、x除以平方和，两个交叉偏导相等，绕单位圆积分却是二π。它在原点有奇点，因此不能把有洞区域上的局部条件直接升级为整个区域路径无关。',[4],['有洞或奇点时，不能只靠交叉偏导相等','实际势函数与定义域必须匹配'])],['路径无关与全微分'])
S(c,'曲线积分练习',[R('圆周，取逆时针方向',r'L:\ x^2+y^2=4'),R('任务',r'\oint_L(x\,dy-y\,dx)=\ ?')],[P('暂停求积分：半径二的圆，逆时针方向，计算x乘dy减y乘dx。可以用参数法，也可以先识别P、Q，再用格林公式。写格林公式时先把原式排成Pdx加Qdy，别因为题目先写了dy，就把P和Q直接按出现顺序认反。最后检查半径在答案中是一次还是平方。',[1,2],['先整理成Pdx加Qdy','核对方向与圆面积'])],['格林公式','第二类曲线积分参数化'],kind='question')
S(c,'曲线积分练习答案',[R('识别与偏导',r'P=-y,\quad Q=x,\quad Q_x-P_y=2'),R('圆盘面积与结果',r'S=4\pi,\qquad I=2\cdot4\pi=8\pi')],[P('答案八π。P是负y，Q是x，交叉偏导相减得到二；半径二的圆盘面积是四π，再乘二得到八π。若用x等于二余弦t、y等于二正弦t，代入以后被积式为四，对零到二π积分也相同。若改成顺时针，结果应为负八π，区域面积本身并不会因此变负。',[1,2],['结果八π，反向时取负','方向作用于积分，不改变几何面积'])],['格林公式'],kind='answer')

c=C('曲面积分与空间积分公式')
S(c,'第一类曲面积分：面积元dS',[R('图形曲面的面积元',r'z=g(x,y),\quad dS=\sqrt{1+g_x^2+g_y^2}\,dx\,dy'),R('例题范围',r'z=x+y,\quad0\leq x,y\leq1'),R('面积',r'\iint_S1\,dS=\iint_{[0,1]^2}\sqrt3\,dx\,dy=\sqrt3')],[P('先看斜平面与它在底面上的投影。第一类曲面积分使用曲面面积元dS，与面的朝向无关。曲面能写成z关于x、y的函数时，面积元是根号一加两个偏导平方，乘投影面积元。例题两个偏导都为一，因此斜面面积是底面面积的根号三倍，不能直接把投影面积当成曲面面积。',[1,2],['第一类使用几何面积元','投影到平面后要乘面积伸缩因子'],phase='surface',anchor='先看斜平面与它在底面上的投影'),P('现在把底面小块对应到斜面上。底面是单位正方形，面积一，所以曲面面积根号三。若被积函数不是常数一，也要把其中的z替换成曲面表达式，再对投影区域积分。第一类与曲线上的第一类很相似：几何长度或面积元非负，改变遍历取向不会让积分自动反号。',[3],['函数中的z也要限制到曲面上','本题面积根号三'],phase='projection',anchor='现在把底面小块对应到斜面上')],['第一类曲面积分'],visual=G('surface_patch'))
S(c,'第二类曲面积分：通量与法向方向',[R('向量形式',r'\iint_S\mathbf F\cdot\mathbf n\,dS'),R('上侧图形曲面',r'\mathbf n\,dS=(-g_x,-g_y,1)\,dx\,dy'),R('同一斜面，取向上',r'\mathbf F=(0,0,1):\quad\iint_S\mathbf F\cdot\mathbf n\,dS=1')],[P('先把斜面上侧的法向箭头画出。第二类曲面积分可看作通量，使用带方向的法向面积。曲面写成z等于g、取向上时，可以把单位法向乘曲面面积元合并成负gx、负gy、一，再乘dxdy。这里已经包含面积变化，不要再额外乘一次第一类公式的根号因子。',[1,2],['第二类必须给定取向','合并法向面积后，不再另乘根号因子'],phase='up',anchor='先把斜面上侧的法向箭头画出'),P('现在沿竖直方向观察穿过斜面的量。向量场是零、零、一，点乘以后只剩一，对单位正方形积分得到一，不是上一页的根号三。因为一题算面积，另一题算指定方向的通量。把曲面取向改成向下，第二类积分结果变成负一，第一类面积仍为正的根号三。',[3],['同一曲面，面积与通量不同','反向使第二类曲面积分变号'],phase='flux',anchor='现在沿竖直方向观察穿过斜面的量')],['第二类曲面积分'],visual=G('surface_flux'))
S(c,'图形曲面通量：三个分量分别代入',[R('取向上的常用模板',r'\iint_S P\,dy\,dz+Q\,dz\,dx+R\,dx\,dy'),R('转成投影区域积分',r'=\iint_D(-Pg_x-Qg_y+R)\,dx\,dy'),R('例题',r'z=x+y,\quad\mathbf F=(x,y,z)'),R('限制到曲面再化简',r'-x-y+(x+y)=0\quad\Longrightarrow\quad I=0')],[P('第二类曲面积分也会写成三个坐标面积元的和。若投影到xy平面、取向上，直接用负P乘gx，减Q乘gy，再加R的模板。注意P、Q、R本身可能含z，必须先限制到曲面z等于g上再计算。投影到别的坐标平面时，公式与符号也要随所解出的变量和取向调整。',[1,2],['先确定投影平面与取向','P、Q、R中的z不能残留未替换']),P('本题曲面仍是z等于x加y，但向量场换成x、y、z。两个偏导都是一，代入得到负x减y加z，再用曲面方程替换z，恰好为零。因此这块斜面的通量为零。不要因为场的三个分量都不恒为零，就断定通量不能为零；真正要积分的是与法向点乘后的组合。',[3,4],['先代曲面，再把三个分量组合','本题组合后恒为零'])],['曲面积分投影计算'])
S(c,'高斯公式：闭合曲面转三重积分',[R('外侧法向的公式',r'\iint_{\partial\Omega}\mathbf F\cdot\mathbf n\,dS=\iiint_\Omega\operatorname{div}\mathbf F\,dV'),R('散度与本例',r'\mathbf F=(x,y,z),\quad\operatorname{div}\mathbf F=P_x+Q_y+R_z=3'),R('单位球面外侧通量',r'I=3\cdot\frac{4\pi}{3}=4\pi')],[P('先把封闭球面的外法向标出来。高斯公式把封闭曲面的外向通量，换成内部体积上的散度积分。散度是P对x、Q对y、R对z相加，不是叉乘。本题向量场x、y、z，散度为三，乘单位球体积，得到四π。若题目要求内侧法向，整个结果再反号。',[1,2],['闭合曲面，默认公式采用外法向','散度是三个相应偏导相加'],phase='outward',anchor='先把封闭球面的外法向标出来'),P('现在把曲面上的计算换成球内小体积的累计。使用前还要确认向量场在包含区域的邻域具有连续一阶偏导。若场在内部某点有奇点，不能只看表面上处处有定义就套公式。还没有闭合的曲面，应考虑补面并扣除补面通量，或者直接计算，而不是忽略缺口。',[3],['定义域条件要覆盖内部','内部有奇点，不能直接使用普通高斯公式'],phase='volume',anchor='现在把曲面上的计算换成球内小体积的累计')],['高斯公式'],visual=G('gauss'))
S(c,'补面法：算整体以后减掉补面',[R('单位上半球外侧与底面',r'S:\ x^2+y^2+z^2=1,\ z\geq0,\quad\mathbf F=(0,0,1)'),R('补成闭合面',r'I_S+I_{\text{disk,down}}=\iiint_\Omega0\,dV=0'),R('底面取向下',r'I_{\text{disk,down}}=-\pi\quad\Longrightarrow\quad I_S=\pi')],[P('先给上半球补上一张底面圆盘。上半球曲面单独并不闭合，不能直接把通量写成散度的体积分。与底面一起围成实体时，上半球外侧向外，底面外法向却是向下。向量场竖直向上，散度为零，所以两个面的总通量为零；这个零不是上半球单独的答案。',[1,2],['先补成闭合面，再用高斯公式','底面的外法向是向下'],phase='cap',anchor='先给上半球补上一张底面圆盘'),P('现在单独计算向下底面的贡献。单位法向与向量场点乘为负一，乘圆盘面积得到负π。因此上半球通量是整体零减底面负π，得到正π。补面法的安全写法，是先列原面加补面等于整体，再移项；凭印象只说最后加一个π，很容易在换取向的题里弄错符号。',[3],['原面等于整体减补面','本题上半球通量为π'],phase='disk',anchor='现在单独计算向下底面的贡献')],['曲面积分补面法'],visual=G('cap_disk'))
S(c,'斯托克斯公式：边界方向跟随法向',[R('公式',r'\oint_{\partial S}\mathbf F\cdot d\mathbf r=\iint_S(\nabla\times\mathbf F)\cdot\mathbf n\,dS'),R('例题的旋度',r'\mathbf F=(-y,x,0),\quad\nabla\times\mathbf F=(0,0,2)'),R('选择单位圆盘，取向上',r'I=\iint_D2\,dx\,dy=2\pi')],[P('先把曲面的法向和边界箭头配成一组。斯托克斯公式联系边界的第二类曲线积分与曲面上的旋度通量。边界方向按右手法则与法向匹配，从法向一侧看是逆时针。向量场需要在相应邻域足够光滑，不能只为了换一个更好算的面，就跨过场没有定义的位置。',[1,2],['右手法则配法向与边界方向','公式使用旋度，不是散度'],phase='boundary',anchor='先把曲面的法向和边界箭头配成一组'),P('现在用同一条圆周张成一张平圆盘。对负y、x、零这个场，旋度是零、零、二，所以取向上的单位圆盘得到二π。它与前面的圆周参数法一致。考试时先识别这是封闭曲线还是封闭曲面，再决定格林、斯托克斯或高斯；名字相近不代表积分对象和使用条件相同。',[3],['边界相同且条件满足，选容易的张成面','闭曲线与闭曲面选用不同公式'],phase='disk',anchor='现在用同一条圆周张成一张平圆盘')],['斯托克斯公式'],visual=G('stokes'))
S(c,'曲面积分练习',[R('区域与向量场',r'\Omega=[0,1]^3,\quad\mathbf F=(x,y,z)'),T('任务','求立方体闭合表面外向通量；再写内向通量')],[P('暂停练习：单位立方体六个面一起组成闭合表面，向量场为x、y、z。先求外向通量，再给内向的结果。请先写散度，再乘体积分的区域，别把六个面逐个展开计算。最后用方向关系自查：内向和外向应该只相差符号，不需要重新做六次积分。',[1,2],['六个面一起构成闭合曲面','先求散度，最后检查法向'])],['高斯公式'],kind='question')
S(c,'曲面积分练习答案',[R('散度与体积',r'\operatorname{div}\mathbf F=3,\qquad V(\Omega)=1'),R('两个取向',r'I_{\text{out}}=3,\qquad I_{\text{in}}=-3')],[P('外向通量为三，内向为负三。散度是一加一加一等于三，单位立方体体积是一，所以高斯公式得到三。若逐面核对，x等于一的面贡献一，x等于零的面贡献零，另外两个坐标方向一样，合计三。这个例子也提醒你，通量按向量场与外法向组合，不是把表面积六直接当成答案。',[1,2],['外向三，内向负三','表面积与通量不是同一个量'])],['高斯公式'],kind='answer')
